const TEXT_PATTERNS = [
    [/^\+(\d+)$/, match => ['float.plus', { amount: match[1] }]],
    [/^\+(\d+) HP$/, match => ['float.plusHp', { amount: match[1] }]],
    [/^\+(\d+) HP \(Pact\)$/, match => ['float.plusHp', { amount: match[1] }]],
    [/^\+(\d+) AP$/, match => ['float.plusAp', { amount: match[1] }]],
    [/^\+(\d+) Actions$/, match => ['float.plusActions', { amount: match[1] }]],
    [/^\+(\d+) Inventory Slots!$/, match => ['float.plusInventorySlots', { amount: match[1] }]],
    [/^\+(\d+) Coins?$/, match => ['float.plusCoins', { amount: match[1] }]],
    [/^\+(\d+) Crystals?$/, match => ['float.plusCrystals', { amount: match[1] }]],
    [/^\+(\d+) Coins\s+\+(\d+) Crystals!?$/, match => ['float.plusCoinsCrystals', { coins: match[1], crystals: match[2] }]],
    [/^\+(\d+) Max HP!?$/, match => ['float.maxHp', { amount: match[1] }]],
    [/^\+(\d+) Max HP \(([^)]+)\)$/, match => ['float.maxHpSource', { amount: match[1], source: match[2] }]],
    [/^\+(\d+) Max Actions!?$/, match => ['float.maxActions', { amount: match[1] }]],
    [/^Refreshed: (\d+) pips$/, match => ['float.refreshedPips', { amount: match[1] }]],
    [/^-(\d+)$/, match => ['float.damage', { amount: match[1] }]],
    [/^-(\d+) Poison$/, match => ['float.poisonDamage', { amount: match[1] }]],
    [/^-(\d+) \(Poison\)$/, match => ['float.poisonDamage', { amount: match[1] }]],
    [/^-(\d+) Fire$/, match => ['float.fireDamage', { amount: match[1] }]],
    [/^-(\d+) Burn$/, match => ['float.burnDamage', { amount: match[1] }]],
    [/^-(\d+) Thorns$/, match => ['float.thornsDamage', { amount: match[1] }]],
    [/^-(\d+) \(Reflect\)$/, match => ['float.reflectDamage', { amount: match[1] }]],
    [/^-(\d+) \(Reflected\)$/, match => ['float.reflectedDamage', { amount: match[1] }]],
    [/^-(\d+) \(Mirrored\)$/, match => ['float.mirroredDamage', { amount: match[1] }]],
    [/^\+(\d+) Leech$/, match => ['float.leech', { amount: match[1] }]],
    [/^(.+) socketed(.*)$/, match => ['float.gemSocketed', { name: match[1], stack: match[2] }]],
    [/^(.+) equipped!$/, match => ['float.equippedItem', { name: match[1] }]],
    [/^(.+) upgraded!$/, match => ['float.upgradedItem', { name: match[1] }]],
    [/^Equipped (.+)$/, match => ['float.equippedArmor', { name: match[1] }]],
    [/^Unequipped (.+)$/, match => ['float.unequippedArmor', { name: match[1] }]],
    [/^(.+) broke!$/, match => ['float.itemBroke', { name: match[1] }]],
    [/^Mimic! Kill in (\d+) turns$/, match => ['float.mimicKill', { turns: match[1] }]],
    [/^Floor Cleared! \+(\d+) coins$/, match => ['float.floorCleared', { amount: match[1] }]],
    [/^Act (\d+)$/, match => ['float.act', { act: match[1] }]],
    [/^Frozen \((\d+)\)$/, match => ['float.frozenTurns', { turns: match[1] }]],
    [/^(\d+) left!$/, match => ['float.turnsLeft', { turns: match[1] }]],
    [/^-(\d+) coins stolen!$/, match => ['float.coinsStolen', { amount: match[1] }]],
    [/^Crit (\d+)%$/, match => ['float.critPercent', { percent: match[1] }]],
    [/^Not enough (.+)!$/, match => ['float.notEnoughCurrency', { currency: match[1] }]],
];

